/// `Accessor = Member | Index`
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Accessor {
    /// A `Member`.
    Member(Member),
    /// A `Index`.
    Index(Index),
}

impl AstNode for Accessor {
    type Language = Lang;
    fn can_cast(kind: SyntaxKind) -> bool {
        Member::can_cast(kind) || Index::can_cast(kind)
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        let node = match syntax.kind() {
            SyntaxKind::MEMBER => Self::Member(Member { syntax }),
            SyntaxKind::INDEX => Self::Index(Index { syntax }),
            _ => return None,
        };
        Some(node)
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::Member(it) => it.syntax(),
            Self::Index(it) => it.syntax(),
        }
    }
}

impl From<Member> for Accessor {
    fn from(node: Member) -> Self {
        Self::Member(node)
    }
}

impl From<Index> for Accessor {
    fn from(node: Index) -> Self {
        Self::Index(node)
    }
}

